#!/usr/bin/env bash
# Copyright 2026 The Stargate Authors
# SPDX-License-Identifier: Apache-2.0
#
# bootstrap-tickets.sh — derive specs/NNN-feature/tickets/T-NNN-*.md from the
# spec-kit tasks.md one time, then never overwrite them.
#
# Why this exists: tasks.md is regenerated by /speckit-tasks whenever the plan
# changes; per-ticket lifecycle state cannot live in tasks.md or it would be
# overwritten on the next regen. So tickets live in their own files (the
# infochat/zecsite model), generated once from tasks.md and maintained
# independently thereafter. The [X]/[ ] markers in tasks.md become a derived
# view from the tickets' `status:` field.
#
# ID format: tasks.md uses `T015`, `T002a`, `T019b` etc. The ticket filename
# uses the same id with a slug: T015-loopback-bind-safety-check.md. The id is
# the stable identifier; the slug is a human affordance.
#
# Dependency inference: tasks.md does not declare deps structurally. This
# script derives `blocked_by` from:
#   (a) phase ordering — every task in Phase N is blocked_by every [X] task
#       in earlier phases (coarse; can be tightened by hand post-bootstrap);
#   (b) explicit prose — "Depends on T003", "Pairs with T013",
#       "Test gate: T012a MUST be authored" etc. in the task body.
# Both are heuristics; review the generated frontmatter before relying on it.
#
# privacy_critical inference: a task is flagged `true` if its body matches any
# of the Constitution-Principle-I/III surface keywords (DNS, routing, SOCKS5,
# auth, token, sidecar contract, bind, header, leak). False positives possible;
# review per ticket.
#
# Usage:
#   scripts/bootstrap-tickets.sh specs/001-tor-route
#   scripts/bootstrap-tickets.sh specs/001-tor-route --dry-run
#
# Safety: refuses to overwrite an existing ticket file unless --force is given.

set -euo pipefail

cd "$(git rev-parse --show-toplevel)"

FEATURE_DIR="${1:?usage: bootstrap-tickets.sh <specs/NNN-feature> [--dry-run|--force]}"
shift || true
DRY_RUN=0
FORCE=0
for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    --force)   FORCE=1 ;;
    *) echo "bootstrap-tickets: unknown flag: $arg" >&2; exit 2 ;;
  esac
done

TASKS_MD="$FEATURE_DIR/tasks.md"
TICKETS_DIR="$FEATURE_DIR/tickets"

[ -f "$TASKS_MD" ] || { echo "bootstrap-tickets: $TASKS_MD not found" >&2; exit 2; }
mkdir -p "$TICKETS_DIR"

TEMPLATE="docs/process/ticket-template.md"
[ -f "$TEMPLATE" ] || { echo "bootstrap-tickets: $TEMPLATE not found" >&2; exit 2; }

TODAY="$(date +%Y-%m-%d)"

# --- slug derivation (mirrors infochat's rule) -------------------------------
# 1. lowercase
# 2. drop non-[a-z0-9 -]
# 3. collapse whitespace, replace space with hyphen
# 4. collapse consecutive hyphens, trim
# 5. truncate to 40 chars, trim trailing hyphen
slugify() {
  local s="$1"
  s="$(printf '%s' "$s" | tr '[:upper:]' '[:lower:]')"
  s="$(printf '%s' "$s" | tr -cd 'a-z0-9 -')"
  s="$(printf '%s' "$s" | tr -s ' ' | sed -E 's/^ //; s/ $//')"
  s="$(printf '%s' "$s" | tr ' ' '-')"
  s="$(printf '%s' "$s" | tr -s '-' | sed -E 's/^-//; s/-$//')"
  s="$(printf '%s' "$s" | cut -c1-40 | sed -E 's/-$//')"
  printf '%s' "$s"
}

# YAML single-quote a string. Single-quoted YAML scalars escape ' as '' and
# otherwise pass everything (backticks, colons, #) through literally. This is
# the safe shape for titles that may contain backticks/colons.
yaml_quote() {
  printf "'%s'" "${1//\'/\'\'}"
}

# --- privacy-critical keyword scan ------------------------------------------
# Matches the Constitution-Principle-I/III surface list from CONTRIBUTING.md.
privacy_keywords='DNS|routing|SOCKS5|socks5|authentication|auth|token|sidecar|contract|bind|header|leak|crypto|ed25519|Argon2'
is_privacy_critical() {
  printf '%s' "$1" | grep -Eq "$privacy_keywords"
}

# --- parse tasks.md ---------------------------------------------------------
# A task line looks like:
#   - [X] T015 [P] Author `compose/...` — <body>
#   - [ ] T012a [P] Unit test for the bind-safety check ...
# State is tracked by phase header (`## Phase N: <name>`).

declare -a ID TITLE BODY PHASE STORY PARALLEL DONE
n=0

current_phase=""
while IFS= read -r line; do
  # Phase header: `## Phase 1: Setup (Shared Infrastructure)`
  if [[ "$line" =~ ^##[[:space:]]+Phase[[:space:]]+([0-9]+):[[:space:]]*(.+)$ ]]; then
    current_phase="${BASH_REMATCH[1]}: ${BASH_REMATCH[2]}"
    continue
  fi
  # Task line: `- [X] T015 ...` or `- [ ] T002a [P] ...`
  if [[ "$line" =~ ^-[[:space:]]*\[([ Xx])\][[:space:]]+(T[0-9]+[a-z]?)[[:space:]]+(.*)$ ]]; then
    mark="${BASH_REMATCH[1]}"
    id="${BASH_REMATCH[2]}"
    rest="${BASH_REMATCH[3]}"
    # Extract [P] and [USx] markers from the start of rest.
    parallel="false"
    story="-"
    while true; do
      if [[ "$rest" =~ ^\[P\][[:space:]]*(.*)$ ]]; then
        parallel="true"; rest="${BASH_REMATCH[1]}"
      elif [[ "$rest" =~ ^\[US([0-9])\][[:space:]]*(.*)$ ]]; then
        story="US${BASH_REMATCH[1]}"; rest="${BASH_REMATCH[2]}"
      else
        break
      fi
    done
    # Title = first sentence (up to — or . or first newline), trimmed, ≤ 70 chars.
    title="$(printf '%s' "$rest" | sed -E 's/[[:space:]]+$//; s/^(.{70}).*$/\1/' )"
    # Truncate at em-dash if present and the result is reasonable length.
    title_short="$(printf '%s' "$title" | sed -E 's/ —.*$//; s/ – .*\$//')"
    [ ${#title_short} -ge 20 ] && title="$title_short"
    ID[n]="$id"
    TITLE[n]="$title"
    BODY[n]="$rest"
    PHASE[n]="$current_phase"
    STORY[n]="$story"
    PARALLEL[n]="$parallel"
    [ "$mark" = "X" -o "$mark" = "x" ] && DONE[n]=1 || DONE[n]=0
    n=$((n + 1))
  fi
done < "$TASKS_MD"

echo "bootstrap-tickets: parsed $n task(s) from $TASKS_MD"

# --- emit one ticket file per task ------------------------------------------
emitted=0
skipped=0
for i in "${!ID[@]}"; do
  id="${ID[$i]}"
  title="${TITLE[$i]}"
  body="${BODY[$i]}"
  phase="${PHASE[$i]}"
  story="${STORY[$i]}"
  parallel="${PARALLEL[$i]}"
  done_flag="${DONE[$i]}"

  slug="$(slugify "$title")"
  [ -z "$slug" ] && slug="task"
  dst="$TICKETS_DIR/$id-$slug.md"

  if [ -f "$dst" ] && [ "$FORCE" -ne 1 ]; then
    skipped=$((skipped + 1))
    continue
  fi

  status="pending"
  [ "$done_flag" = "1" ] && status="done"

  if is_privacy_critical "$body"; then
    pc="true"
  else
    pc="false"
  fi

  # Build a minimal frontmatter. The ticket-template.md has the full schema;
  # bootstrap emits only the load-bearing fields and a Context pointer back to
  # tasks.md. The analyze/acceptance sections are filled at /start time per
  # the zecsite pattern (don't pre-write acceptance; derive it from ground
  # truth when the ticket is picked up).
  if [ "$DRY_RUN" = "1" ]; then
    echo "  (dry-run) would write: $dst"
    continue
  fi

  {
    echo "---"
    echo "id: $id"
    printf 'title: %s\n' "$(yaml_quote "$title")"
    echo "status: $status"
    echo "created: $TODAY"
    echo "last_updated: $TODAY"
    echo "source: tasks.md#$id"
    echo "phase: \"$phase\""
    printf 'story: %s\n' "$(yaml_quote "$story")"
    echo "blocked_by: []   # TODO: derive from phase ordering + prose deps"
    echo "parallel: $parallel"
    echo "files_budget: 8   # TODO: tighten per task"
    echo "privacy_critical: $pc"
    echo "complexity: low   # TODO: set per task"
    echo "risk: low"
    echo "round_cap: 2"
    echo "spec_refs: []   # TODO: cite spec.md § at /start"
    echo "decision_refs: []"
    echo "reviews: {}"
    echo "overrides: []"
    echo "aborted_attempts: []"
    echo "reopens: []"
    echo "redteam_findings: []"
    echo "clarity_check: {}"
    echo "---"
    echo ""
    echo "# $id: $title"
    echo ""
    echo "## Context"
    echo ""
    echo "Derived from \`$TASKS_MD\` — see the full task body there. This"
    echo "ticket is the executable work unit; the tasks.md entry is the"
    echo "spec-kit plan that survives \`/speckit-tasks\` regeneration."
    echo ""
    echo "> **Full task body (verbatim from tasks.md):**"
    echo ">"
    echo "> $body"
    echo ""
    echo "## Analysis"
    echo ""
    if [ "$pc" = "true" ]; then
      echo "*(Required — \`privacy_critical: true\`. Fill at \`/start\` per"
      echo "\`docs/process/analysis.md\`.)*"
    else
      echo "*(Omit — not privacy-critical and not high-complexity.)*"
    fi
    echo ""
    echo "## Acceptance"
    echo ""
    echo "*(Derive from the spec at \`/start\` — see \`docs/process/ticket-template.md\`"
    echo "for the preferred shapes: named test, behavioral assertion, runnable command.)*"
    echo ""
    echo "## Out-of-scope"
    echo ""
    echo "*(Fill at \`/start\` if the task body references exclusions or other tickets' work.)*"
    echo ""
    echo "## Notes"
    echo ""
    echo "Derived by \`scripts/bootstrap-tickets.sh\` on $TODAY."
  } > "$dst"

  emitted=$((emitted + 1))
done

echo "bootstrap-tickets: emitted=$emitted skipped=$skipped (already present)"
echo "Next: review the generated TODO comments, then run scripts/lint-ticket.py on each."
